// VSTDM3: a bundle in another format is refused by name.
//
// tom_ast_model 0.3.0 mirrors analyzer 14's AST, and the decision was to keep
// no reader for older bundles: bundles are generated by a toolchain whose
// versions match the app. So the format stamp moved to 2.0, and a bundle
// stamped otherwise is refused with a message naming both versions, rather
// than failing deep inside a node decoder with a null cast.
library;

import 'package:test/test.dart';
import 'package:tom_d4rt_ast/runtime.dart';

void main() {
  group('VSTDM3: the bundle format version is enforced', () {
    Map<String, dynamic> bundleJson(String version) => {
      AstBundleFormat.keyVersion: version,
      AstBundleFormat.keyEntryPoint: 'main.dart',
      AstBundleFormat.keyModules: <String, dynamic>{
        'main.dart': SCompilationUnit(offset: 0, length: 0).toJson(),
      },
    };

    test('F-VSTDM3-7: the format is 2.0 and a 2.0 bundle loads '
        '[2026-11-06]', () {
      expect(AstBundleFormat.version, '2.0');
      final bundle = AstBundle.fromJson(bundleJson('2.0'));
      expect(bundle.entryPointUri, 'main.dart');
    });

    test('F-VSTDM3-8: a 1.0 bundle is refused, naming both versions '
        '[2026-11-06]', () {
      expect(
        () => AstBundle.fromJson(bundleJson('1.0')),
        throwsA(
          isA<ArgumentD4rtException>().having(
            (e) => e.message,
            'message',
            allOf(contains('"1.0"'), contains('"2.0"'), contains('regenerate')),
          ),
        ),
      );
    });

    test('F-VSTDM3-9: a 1.0 manifest is refused the same way [2026-11-06]', () {
      expect(
        () => AstBundleManifest.fromJson({
          AstBundleFormat.keyVersion: '1.0',
          AstBundleFormat.keyEntryPoint: 'main.dart',
          AstBundleFormat.keyFiles: <String, dynamic>{},
        }),
        throwsA(
          isA<ArgumentD4rtException>().having(
            (e) => e.message,
            'message',
            allOf(contains('"1.0"'), contains('"2.0"')),
          ),
        ),
      );
    });
  });
}
